func CommandInfo(name string) (CommandMetadata, bool) {
	metadata, ok := commandMetadata[name]
	if ok {
		metadata = cloneCommandMetadata(metadata)
	}
	return metadata, ok
}

func cloneCommandMetadata(metadata CommandMetadata) CommandMetadata {
	if metadata.FieldSince != nil {
		values := metadata.FieldSince
		metadata.FieldSince = make(map[string]uint32, len(metadata.FieldSince))
		for name, since := range values {
			metadata.FieldSince[name] = since
		}
	}
	if metadata.FieldCapabilities != nil {
		values := metadata.FieldCapabilities
		metadata.FieldCapabilities = make(map[string]string, len(metadata.FieldCapabilities))
		for name, capability := range values {
			metadata.FieldCapabilities[name] = capability
		}
	}
	return metadata
}

func EventInfo(name string) (EventMetadata, bool) {
	metadata, ok := eventMetadata[name]
	if ok {
		metadata.Streams = append([]string(nil), metadata.Streams...)
	}
	return metadata, ok
}

func ProfileInfo(name Profile) (ProfileMetadata, bool) {
	metadata, ok := profileMetadata[name]
	if ok {
		metadata.Inherits = append([]Profile(nil), metadata.Inherits...)
	}
	return metadata, ok
}

